DROP TABLE IF EXISTS `database_sektor_olahan_pangan`;
CREATE TABLE `database_sektor_olahan_pangan` (
  `id` int(11) NOT NULL,
  `country` varchar(100) NOT NULL,
  `country_slug` varchar(100) NOT NULL,
